#!/usr/bin/env python3
"""Render a framework-free website. Update content, facts and config, then run this."""
import json,html,re,xml.etree.ElementTree as ET
from datetime import date
from pathlib import Path
ROOT=Path(__file__).resolve().parent.parent
CONFIG=json.loads((ROOT/'_ops/config.json').read_text());BASE=CONFIG['base'].rstrip('/')+'/'
F=json.loads((ROOT/'_ops/facts.json').read_text());APP='https://apps.apple.com/app/id6754815949'
E=html.escape;pages={}
AUTHOR=BASE+'about.html#author';APP_ENTITY=BASE+'#app';WEBSITE=BASE+'#website'
PERSON={'@context':'https://schema.org','@type':'Person','@id':AUTHOR,'name':'Mohamed Elatabany','url':BASE+'about.html','sameAs':['https://github.com/Atabany']}
RATING=f"{F['averageUserRating']:.1f}".removesuffix('.0')
CHECKED=date.fromisoformat(F['checkedDate']).strftime('%B %d, %Y').replace(' 0',' ')
FACT=f"Photo Cleaner: Swipe & Delete is an iPhone photo-cleanup app by Mohamed Elatabany for iOS 17 or later. It offers a personal cleanup plan, duplicate and similar-photo review, screenshot and large-video review, and swipe-to-keep or mark-for-removal controls. Photo analysis happens on your device; photos are not uploaded for scanning. Start with a one-time free allowance; Pro unlocks unlimited swipes and advanced cleanup tools, with subscription and one-time purchase options depending on availability. Rated {RATING} stars on the US App Store, checked {CHECKED}."

def cta(tag,nav=False):
 url=f'https://apps.apple.com/app/apple-store/id6754815949?pt=127826363&ct=web_{tag[:34]}&mt=8'
 return f'<a class="download {"nav-download" if nav else ""}" href="{E(url)}" aria-label="Download Photo Cleaner: Swipe and Delete on the App Store"><img class="cta-icon" src="assets/app-icon.webp" width="50" height="50" alt=""><img class="badge" src="assets/app-store.svg" width="150" height="50" alt="Download on the App Store"></a>'

def facts():return '<aside class="fact-block" aria-label="Verified app facts">'+E(FACT)+'</aside>'

def faq(items):
 return '<section id="faq"><h2>Questions, answered.</h2>'+''.join(f'<details><summary>{E(x["question"])}</summary><p>{E(x["answer"])}</p></details>' for x in items)+'</section>'

def render(slug,title,desc,body,kind='WebPage',faqs=None,noindex=False,modified=None):
 modified=modified or CONFIG['updated']
 file='index.html' if not slug else slug+'.html';url=BASE+('' if not slug else file)
 ld=[{'@context':'https://schema.org','@type':kind,'@id':url+'#page','name':title,'url':url,'description':desc,'isPartOf':{'@id':WEBSITE},'about':{'@id':APP_ENTITY}},PERSON]
 if kind=='Article':
  ld[0].update(headline=title,author={'@id':AUTHOR},datePublished='2026-10-04',dateModified=modified,publisher={'@id':AUTHOR},mainEntityOfPage=url,image=BASE+'assets/og.png',citation=list(dict.fromkeys(html.unescape(u) for u in re.findall(r'href="(https://[^"]*)"',body) if 'ct=web_' not in u)))
 if not noindex:ld.append({'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Home','item':BASE}]+([{'@type':'ListItem','position':2,'name':title,'item':url}] if slug else [])})
 if faqs:ld.append({'@context':'https://schema.org','@type':'FAQPage','mainEntity':[{'@type':'Question','name':x['question'],'acceptedAnswer':{'@type':'Answer','text':x['answer']}} for x in faqs]})
 if not slug:ld.append({'@context':'https://schema.org','@type':'MobileApplication','name':F['trackName'],'operatingSystem':'iOS 17+','applicationCategory':'UtilitiesApplication','url':url,'downloadUrl':APP,'author':{'@type':'Person','name':'Mohamed Elatabany'},'image':BASE+'assets/app-icon.webp','aggregateRating':{'@type':'AggregateRating','ratingValue':F['averageUserRating'],'ratingCount':F['userRatingCount'],'bestRating':5,'worstRating':1}})
 if not slug:
  ld[-1].update({'@id':APP_ENTITY,'sameAs':[APP],'identifier':{'@type':'PropertyValue','propertyID':'Apple App Store ID','value':CONFIG['appId']},'softwareVersion':F['version'],'inLanguage':[x.lower() for x in F['languageCodesISO2A']],'author':{'@id':AUTHOR},'featureList':['Personal cleanup plan','Duplicate and similar-photo review','Screenshot and large-video review','Swipe to keep or mark for removal','Review in-app Trash before deletion','On-device photo analysis']})
  ld.append({'@context':'https://schema.org','@type':'WebSite','@id':WEBSITE,'url':BASE,'name':F['trackName'],'inLanguage':'en','publisher':{'@id':AUTHOR}})
 ld_json=json.dumps(ld,ensure_ascii=False).replace('</','<'+chr(92)+'/')
 out=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(title)}</title><meta name="description" content="{E(desc)}"><meta name="apple-itunes-app" content="app-id=6754815949, app-argument={E(url)}"><meta name="theme-color" content="#0e0f12"><link rel="canonical" href="{E(url)}"><link rel="icon" href="assets/app-icon.webp"><link rel="stylesheet" href="style.css?v={CONFIG['cssVersion']}"><meta property="og:title" content="{E(title)}"><meta property="og:description" content="{E(desc)}"><meta property="og:url" content="{E(url)}"><meta property="og:type" content="{'article' if kind=='Article' else 'website'}"><meta property="og:image" content="{BASE}assets/og.png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta name="twitter:card" content="summary_large_image">{'<meta name="robots" content="noindex">' if noindex else '<meta name="robots" content="index,follow,max-snippet:-1,max-image-preview:large,max-video-preview:-1">'}<meta name="google-site-verification" content="{E(CONFIG.get('googleSiteVerification',''))}"><script type="application/ld+json">{ld_json}</script><script src="site.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a><header><nav class="wrap" aria-label="Main navigation"><a class="wordmark" href="./"><img src="assets/app-icon.webp" width="42" height="42" alt=""><span>Swipe &amp; Delete<small>PHOTO CLEANER</small></span></a><div class="nav-links"><a href="guides.html">Guides</a><a href="cleanup-planner.html">Cleanup planner</a><a href="support.html">Support</a>{cta(slug or 'home',True)}</div></nav></header><main id="main" class="wrap">{body}</main><footer><div class="wrap"><div class="footer-links"><a href="about.html">About the maker</a><a href="how-it-works.html">How it works</a><a href="guides.html">Photo cleanup guides</a><a href="best-photo-cleaner-apps.html">Compare apps</a><a href="support.html">Support</a><a href="privacy.html">Privacy</a><a href="terms.html">Terms</a></div><div class="footer-bottom"><span>© 2026 Mohamed Elatabany · Photo Cleaner: Swipe &amp; Delete</span><span>Your photos. Your decisions.</span></div></div></footer></body></html>'''
 (ROOT/file).write_text(out+'\n');pages[file]={'title':title,'url':url,'noindex':noindex,'modified':modified}

def article(slug,title,desc,heading,intro,sections,faqs=None,updated='2026-10-04'):
 month=date.fromisoformat(updated).strftime('%B %Y')
 toc='<nav class="toc" aria-label="On this page"><b>On this page</b><ul>'+''.join(f'<li><a href="#{E(s["id"])}">{E(s["title"])}</a></li>' for s in sections)+('</ul></nav>')
 body=f'<article class="page"><div class="breadcrumbs"><a href="./">Home</a> / <a href="guides.html">Guides</a></div><h1>{E(heading)}</h1><p class="lead">{E(intro)}</p><p class="byline">By <a href="about.html">Mohamed Elatabany</a> · Updated {month} · <a href="support.html">Suggest a correction</a></p>{toc}'
 body+=''.join(f'<section id="{E(s["id"])}"><h2>{E(s["title"])}</h2>{s["html"]}</section>' for s in sections)
 if faqs:body+=faq(faqs)
 body+=facts()+cta(slug)+'<p class="notice">Start free. Pro purchases are optional. Review the current options in the app.</p><p><a href="guides.html">More guides →</a> · <a href="cleanup-planner.html">Build a cleanup plan →</a></p></article>'
 render(slug,title,desc,body,'Article',faqs,modified=updated)

def simple(slug,title,desc,body):render(slug,title,desc,f'<article class="page"><div class="breadcrumbs"><a href="./">Home</a></div><h1>{E(title)}</h1><p class="byline">Updated October 2026</p>{body}</article>')

home=f'''<section class="hero"><div><p class="eyebrow">A little less clutter. A lot more room.</p><h1>Keep the memories.<br><span>Lose the extras.</span></h1><p class="lead">A personal plan for your camera roll. Find repeated shots, review what takes up space, and decide what stays—one easy swipe at a time.</p>{cta('home')}<div class="chips"><span>iPhone · iOS 17+</span><span>Photo analysis on-device</span><span>Free to start</span></div><p class="rating"><b>★★★★★</b> {RATING} stars on the US App Store · checked {CHECKED}</p></div><div class="hero-art"><video data-motion data-src="assets/onboarding.mp4" muted loop playsinline preload="none" poster="assets/onboarding-poster.webp" width="1080" height="1500" aria-label="The app's onboarding animation, using example photos and storage numbers"></video><button class="motion-button" id="motion-toggle" hidden>Play animation</button></div></section>
<section class="block"><p class="eyebrow">A calmer way to clean</p><h2>You decide what goes.<br>We help you find where to start.</h2><div class="grid"><div class="card"><span class="number">01 / FIND YOUR FOCUS</span><h3>Start with a plan.</h3><p>Choose your cleanup priorities. See a storage estimate and a focused place to begin, instead of another endless grid.</p></div><div class="card"><span class="number">02 / KEEP THE GOOD ONES</span><h3>A swipe. A decision.</h3><p>Swipe right to keep, left to mark for removal. Compare similar shots, revisit screenshots, and give large videos a closer look.</p></div><div class="card"><span class="number">03 / CHECK BEFORE DELETING</span><h3>Review, then remove.</h3><p>Undo a swipe or restore an item from the in-app Trash Bin before confirming deletion. You're in control of the final choice.</p></div></div><div class="screens"><img src="assets/screen-2.webp" width="440" height="956" alt="App screenshot: choose cleanup priorities" loading="lazy"><img src="assets/screen-3.webp" width="440" height="956" alt="App screenshot: swipe to review photos" loading="lazy"><img src="assets/screen-4.webp" width="440" height="956" alt="App screenshot: compare similar photos" loading="lazy"></div><p class="notice">Screens and animation use a demonstration library. Your results depend on your photos.</p></section>
<section class="block tool-promo"><div><p class="eyebrow">A useful place to start</p><h2>What should you clean up first?</h2><p class="section-intro">A handful of long videos can outweigh hundreds of screenshots. Use our free planner to estimate the space in the items you're considering removing.</p><a class="text-button" href="cleanup-planner.html">Build my cleanup plan →</a><p class="notice">Runs in your browser. No photos, uploads, or account.</p></div><div class="sample-plan"><p class="eyebrow">An example, not a promise</p><div><span>10 videos × 200 MB</span><b>2 GB</b></div><div><span>100 photos × 3 MB</span><b>0.3 GB</b></div><div><span>100 screenshots × 1 MB</span><b>0.1 GB</b></div><p>Start with the videos. Check each one before deleting.</p></div></section>
<section class="block"><p class="eyebrow">A real App Store review</p><blockquote class="quote" lang="es">“Práctica, sencilla, genial!”</blockquote><p class="quote-note">Daniiel601 · Mexico · 5 stars · August 18, 2026<br>“Practical, simple, great!” — English translation</p></section>
<section class="block"><p class="eyebrow">Good decisions start with good information</p><h2>A little guidance for your library.</h2><div class="grid"><div class="card"><h3>Repeated photos?</h3><p>Understand Apple's Duplicates collection and when similar shots need a closer look.</p><a href="delete-duplicate-photos-iphone.html">Find and review duplicates →</a></div><div class="card"><h3>iCloud switched on?</h3><p>Know what deleting a photo means across your devices before starting a cleanup.</p><a href="icloud-photo-deletion.html">Read the iCloud guide →</a></div><div class="card"><h3>Too much to sort?</h3><p>Break an overwhelming camera roll into small, deliberate review sessions.</p><a href="swipe-photo-cleanup.html">Make a manageable plan →</a></div></div></section>
<section class="block"><p class="eyebrow">Photo analysis stays on your iPhone</p><h2>Your library deserves care.</h2><p class="section-intro">Your photos aren't uploaded for scanning or cleanup decisions. Purchase services are handled by Apple and RevenueCat. Read exactly what that means in our privacy information.</p><a href="privacy.html">Read the privacy information →</a>{facts()}</section><section class="block bottom-cta"><div><h2>Make room for your next memory.</h2><p>Photo Cleaner: Swipe &amp; Delete · by Mohamed Elatabany</p></div>{cta('home_footer')}</section>'''
HOME_FAQS=[{'question':'What is Photo Cleaner: Swipe & Delete?','answer':'It is an iPhone photo-cleanup app by Mohamed Elatabany. It offers a personal cleanup plan, duplicate and similar-photo review, screenshot and large-video review, and swipe controls. You review marked items before confirming deletion.'},{'question':'Does it upload my photos for analysis?','answer':'Photo analysis runs on your iPhone; photos are not uploaded for scanning or cleanup decisions. Apple and RevenueCat process purchase services. Apple Photos may download iCloud media when requested.'},{'question':'Is Photo Cleaner: Swipe & Delete free?','answer':'It starts with a one-time free allowance. Optional Pro purchases unlock unlimited swipes and advanced cleanup tools. Current purchase options and terms appear in the app.'},{'question':'What happens when I delete an iCloud photo?','answer':'When iCloud Photos is enabled, deleting an item also removes it from other devices using that synced library. Check your selections and keep a separate backup of irreplaceable media.'}]
home+='<div class="block">'+faq(HOME_FAQS)+'<p><a href="how-it-works.html">How photo review works and its limits →</a></p></div>'
render('','Photo Cleaner: Swipe & Delete — Your Personal Cleanup Plan','Find repeated photos, review large videos, and follow a personal cleanup plan. Photo analysis stays on your iPhone. Free to start.',home,faqs=HOME_FAQS)

simple('about','About Photo Cleaner: Swipe & Delete','Meet Mohamed Elatabany, the maker of Photo Cleaner: Swipe & Delete, and learn how our photo cleanup guides are checked.','''<p class="lead">Made by Mohamed Elatabany to help you make deliberate choices about your photo library.</p><section><h2>A plan, not a rush.</h2><p>Photo Cleaner: Swipe &amp; Delete combines a personal cleanup plan with focused review sessions. Its purpose is to help you find unnecessary photos and videos while keeping the decisions in your hands.</p><p>The App Store developer is Mohamed Elatabany. <a href="https://github.com/Atabany">View my public GitHub profile</a> or <a href="https://apps.apple.com/app/apple-store/id6754815949?pt=127826363&amp;ct=web_about&amp;mt=8">verify this app's developer on the App Store</a>.</p></section><section><h2>How we write guides.</h2><p>Guides explain Apple's built-in options first and link to Apple documentation. App descriptions are checked against the app's code and live App Store listing. Comparisons use competitors' own current listings and documentation. We identify estimates, explain limitations, and avoid invented ratings or claims of guaranteed results.</p><p>These guides are published by the developer of a photo-cleanup app; comparisons therefore have a commercial interest. Choose the built-in Photos app if it solves your problem.</p><p>Menu locations change between iOS versions. Check the date on each guide, and <a href="support.html">send a correction</a> if something needs updating.</p></section>'''+facts())
simple('support','Support for Photo Cleaner: Swipe & Delete','Get help with photo access, cleanup, restoring purchases, or billing in Photo Cleaner: Swipe & Delete.','''<p class="lead">Need a hand? <a href="mailto:atabany.apps@gmail.com?subject=Photo%20Cleaner%20Swipe%20%26%20Delete%20Support">Email atabany.apps@gmail.com</a>.</p><p>Include your iPhone model, iOS version, app version, and what happened. Please avoid sending private photos or purchase credentials.</p><section><h2>Photo access</h2><p>The app can only review the photos you allow it to access. Use iPhone Settings to find the app's Photos permission and adjust access. Limited access means only selected photos are available for review.</p></section><section><h2>Recover a photo</h2><p>Before confirming deletion, restore marked items from the in-app Trash Bin. After deleting, check Recently Deleted in Apple's Photos app. Apple normally keeps deleted items there for 30 days, unless you permanently remove them earlier. When iCloud Photos is enabled, deletion syncs to your other devices.</p><p><a href="https://support.apple.com/en-us/104967">Apple's deletion and recovery instructions</a></p></section><section><h2>Purchases and subscriptions</h2><p>Use Restore Purchases on the paywall with the Apple Account that made the purchase. To manage a subscription, open Settings, tap your name, then Subscriptions. Apple handles billing and refund requests.</p><p><a href="https://support.apple.com/en-us/118428">Manage or cancel a subscription</a> · <a href="https://reportaproblem.apple.com/">Request a refund from Apple</a></p></section><section><h2>Website corrections</h2><p>Include the page URL and the detail that appears incorrect. The maker reviews corrections; no response time is guaranteed.</p></section>''')
simple('privacy','Privacy information','How Photo Cleaner: Swipe & Delete handles on-device photo analysis, purchase services, and this website.','''<p class="lead">Photo analysis happens on your device. Your photos are not uploaded for scanning or cleanup decisions.</p><section><h2>Your Photos library</h2><p>The app uses Apple's Photos permission to access your authorized library. Duplicate detection, similar-photo review, and cleanup decisions are processed on your device. Photos stored in iCloud may be downloaded by Apple's Photos services when you request them; that is separate from uploading photos to our servers.</p><p>Review progress and preferences are stored locally. The app also stores its free-allowance usage locally, including in Keychain. Revoking Photos access prevents further access to your library through the app.</p></section><section><h2>Purchase services</h2><p>Apple processes in-app purchases. The app uses RevenueCat to manage purchase status and Pro entitlements. Purchase records, app-user identifiers, and relevant device or usage information may be processed by those services to manage entitlements and operate their services. On-device photo analysis does not mean that no information ever leaves the device.</p><p><a href="https://www.revenuecat.com/privacy/">RevenueCat privacy policy</a> · <a href="https://www.apple.com/legal/privacy/">Apple privacy policy</a></p></section><section><h2>This website and the planner</h2><p>This website does not include advertising, third-party fonts, or analytics scripts. The cleanup planner calculates estimates in your browser and does not send your entries or photos to us. GitHub Pages hosts the website and can process standard request information needed to serve it.</p><p>Download links contain Apple's campaign parameters so aggregate downloads can be attributed in App Store Connect when Apple reports them. The links do not contain your photo data.</p></section><section><h2>Current policy and contact</h2><p>This page explains the implementation checked on October 4, 2026. The <a href="https://atabany.notion.site/Privacy-Policy-29fa2ea1ded681fc975bfcad48899908?pvs=74">privacy policy currently linked from the App Store</a> remains available. If you email support, your message and contact details are used to respond. Contact <a href="mailto:atabany.apps@gmail.com">atabany.apps@gmail.com</a> with privacy questions or requests to access or delete information held by the developer. Local review data can be reset in the app; purchase-allowance records may persist in Keychain. Apple and RevenueCat maintain their own records under their policies.</p></section>''')
simple('terms','Terms of use','Terms and purchase information for Photo Cleaner: Swipe & Delete and its website cleanup planner.','''<p class="lead">The app uses <a href="https://www.apple.com/legal/internet-services/itunes/dev/stdeula/">Apple's standard end-user license agreement</a>.</p><section><h2>Keep control of your library</h2><p>Review your selections before confirming deletion. Maintain a separate backup of irreplaceable media. With iCloud Photos enabled, deletion applies across synced devices. Permanently removed items cannot be restored through Recently Deleted.</p></section><section><h2>Pro purchases</h2><p>The app offers a free starting allowance and optional Pro purchases. Available subscriptions and one-time purchases, their terms, and any trial eligibility are displayed before purchase. Apple manages payment and subscription billing. Manage or cancel subscriptions through your Apple Account settings.</p></section><section><h2>Website estimates</h2><p>The cleanup planner uses the counts and average file sizes you enter. It does not inspect your library, guarantee recoverable storage, or delete anything. File size and local device space can differ, particularly with optimized iCloud Photos.</p></section><p><a href="support.html">Contact support</a> for questions.</p>''')
planner='''<p class="lead">Estimate the space in unwanted photos, screenshots, and videos, then see which group is worth reviewing first. Everything runs in your browser; no library access or uploads.</p><form class="planner" id="cleanup-planner"><div class="planner-grid"><label>Unwanted photos, excluding screenshots<input id="photos" type="number" value="100" min="0" max="1000000" step="1" required></label><label>Average photo size (MB)<input id="photo-size" type="number" value="3" min="0.01" max="10000" step="any" required></label><label>Old screenshots<input id="screenshots" type="number" value="100" min="0" max="1000000" step="1" required></label><label>Average screenshot size (MB)<input id="screen-size" type="number" value="1" min="0.01" max="10000" step="any" required></label><label>Unwanted videos<input id="videos" type="number" value="10" min="0" max="1000000" step="1" required></label><label>Average video size (MB)<input id="video-size" type="number" value="200" min="0.01" max="1000000" step="any" required></label></div><div class="planner-output" id="planner-result" role="status" aria-live="polite"><strong>2.4 GB in this example</strong><p>Videos account for 2 GB, photos for 0.3 GB, and screenshots for 0.1 GB.</p></div><noscript><p>Use the reference table below: multiply each count by its average size, add the results, then divide MB by 1,000 for decimal GB.</p></noscript></form><section><h2>The math, without the guesswork.</h2><p>Estimated GB = (photo count × average photo MB + screenshot count × average screenshot MB + video count × average video MB) ÷ 1,000. Categories must not overlap. The default sizes are illustrative inputs, not measured averages.</p><div class="table-wrap"><table><caption>Reference examples with explicit assumptions</caption><thead><tr><th>Group</th><th>Count</th><th>Assumed size each</th><th>Total file size</th></tr></thead><tbody><tr><td>Photos</td><td>100</td><td>3 MB</td><td>0.3 GB</td></tr><tr><td>Screenshots</td><td>100</td><td>1 MB</td><td>0.1 GB</td></tr><tr><td>Videos</td><td>10</td><td>200 MB</td><td>2 GB</td></tr><tr><td>Combined, no overlap</td><td>210</td><td>Mixed</td><td>2.4 GB</td></tr></tbody></table></div></section><section><h2>Use sizes from your own library.</h2><p>Open a photo or video in Photos and open its information view to inspect its details. Sample a few unwanted items rather than assuming every file is the same size. Videos vary dramatically with duration, resolution, frame rate and recording format.</p><p>Check Settings → General → iPhone Storage before and after cleanup. With Optimize iPhone Storage enabled, full originals may already live in iCloud, so deleting total file bytes may free much less local space. Recently Deleted can also retain removed items. Keep its recovery window when you can; permanently deleting an item removes that safety net.</p><p><a href="https://support.apple.com/en-us/108429">Apple: check device storage</a> · <a href="https://support.apple.com/en-us/105061">Apple: manage photo storage</a></p></section><section><h2>Turn the estimate into a safe plan.</h2><ol><li>Start with the group contributing the most file bytes.</li><li>Review items individually and keep anything irreplaceable.</li><li>Check iCloud syncing and your separate backup before confirming deletion.</li><li>Check actual iPhone storage after Photos has processed the change.</li></ol><p>The planner never scans or deletes your photos. For focused review on your iPhone, Photo Cleaner: Swipe &amp; Delete offers a personal cleanup plan, similar-photo comparisons, and an in-app Trash Bin for review before confirmed deletion.</p></section>'''
simple('cleanup-planner','Photo Cleanup Planner — Estimate Storage to Review','Estimate space in unwanted photos, screenshots, and videos. Find where to start with a local-only planner and a reference table.',planner+facts()+cta('cleanup_planner'))

guides_file=ROOT/'_ops/guides.json'
guides=json.loads(guides_file.read_text()) if guides_file.exists() else []
for g in guides:
 sections=g['sections']+[{'id':'sources','title':'Sources and further reading','html':'<ul>'+''.join(f'<li><a href="{E(s["url"])}">{E(s["title"])}</a></li>' for s in g['sources'])+'</ul>'}]
 article(g['slug'],g['title'],g['description'],g['heading'],g['intro'],sections,g['faqs'],updated=g.get('updated','2026-10-04'))
links=''.join(f'<a class="guide-link" href="{E(g["slug"])}.html">{E(g["heading"])} <span>→</span><small>{E(g["description"])}</small></a>' for g in guides)
simple('guides','iPhone Photo Cleanup Guides','Practical iPhone photo cleanup guides: Apple Photos options, similar shots, screenshots, videos, iCloud deletion, and a manageable review plan.','<p class="lead">Start with the built-in options. Learn where a focused review can help.</p><div class="guides-list">'+links+'<a class="guide-link" href="best-photo-cleaner-apps.html">Compare photo cleanup apps →<small>An honest guide by the maker of Swipe &amp; Delete.</small></a><a class="guide-link" href="cleanup-alternative.html">Looking for a Cleanup alternative? →<small>Compare your needs and the apps’ current listings.</small></a></div>')
render('404','Page not found — Swipe & Delete','Return to Photo Cleaner: Swipe & Delete or find a photo-cleanup guide.','<article class="page"><h1>This page has moved out of the frame.</h1><p><a href="./">Return home</a> or <a href="guides.html">browse the guides</a>.</p></article>',noindex=True)
# Extra comparison pages are rendered by a separate content file when present.
extra=ROOT/'_ops/comparisons.json'
if extra.exists():
 for g in json.loads(extra.read_text()):article(**g)
for g in json.loads((ROOT/'_ops/product-pages.json').read_text()):article(**g)
urls=[p['url'] for p in pages.values() if not p['noindex']]
sitemap=ET.Element('urlset',xmlns='http://www.sitemaps.org/schemas/sitemap/0.9')
for url in urls:
 node=ET.SubElement(sitemap,'url');ET.SubElement(node,'loc').text=url;ET.SubElement(node,'lastmod').text=next(p['modified'] for p in pages.values() if p['url']==url)
